function ToggleAbstract(){const e=document.getElementById("abstract-1"),t=document.getElementById("abstract_button_1"),n=e.classList.contains("hidden");if(n){const n=e.cloneNode(!0);n.classList.remove("hidden"),n.removeAttribute("id"),n.style.position="absolute",n.style.visibility="hidden",n.style.maxHeight="none",n.style.pointerEvents="none",n.style.width=e.getBoundingClientRect().width+"px",n.style.margin="0",n.style.boxSizing="border-box",e.parentNode.insertBefore(n,e.nextSibling);const s=n.scrollHeight;n.remove(),e.style.setProperty("--abstract-height",s+"px"),e.classList.remove("hidden"),t.setAttribute("title","Hide abstract")}else e.classList.add("hidden"),t.setAttribute("title","Show abstract")}document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("abstract_button_1");e&&e.addEventListener("click",ToggleAbstract)})